.libPaths(unique(c('/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.5','/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.4',.libPaths())))
suppressPackageStartupMessages({library(data.table);library(qs)})
root<-'/home/data/t070721/codex_workspace/Bladder Metabolism/mp10_subtype_screen_round1_v2';rows<-list()
for(fp in list.files(file.path(root,'objects/networks'),pattern='epi_state.*qs$',full.names=TRUE)){o<-qread(fp);pr<-o$net$prob;pv<-o$net$pval;nodes<-dimnames(pr)[[1]];lrs<-dimnames(pr)[[3]]
 for(tar in setdiff(nodes,c('Epi_MP10_low','Epi_MP10_high')))for(dir in c('epi_to_TME','TME_to_epi')){a<-if(dir=='epi_to_TME')pr['Epi_MP10_low',tar,]else pr[tar,'Epi_MP10_low',];b<-if(dir=='epi_to_TME')pr['Epi_MP10_high',tar,]else pr[tar,'Epi_MP10_high',];pa<-if(dir=='epi_to_TME')pv['Epi_MP10_low',tar,]else pv[tar,'Epi_MP10_low',];pb<-if(dir=='epi_to_TME')pv['Epi_MP10_high',tar,]else pv[tar,'Epi_MP10_high',];d<-b-a;ok<-(pa<.05&a>0)|(pb<.05&b>0);ii<-head(order(ifelse(ok,abs(d),-Inf),decreasing=TRUE),5);ii<-ii[ok[ii]&d[ii]!=0];if(length(ii))rows[[length(rows)+1]]<-data.table(scope=o$scope,network_level=o$network_level,TME_type=tar,direction=dir,LR_id=lrs[ii],prob_low=a[ii],prob_high=b[ii],raw_delta=d[ii],P_low=pa[ii],P_high=pb[ii],note='Largest raw within-object differences among internally supported LR; descriptive only, not biological ranking or patient validation')}
};fwrite(rbindlist(rows),file.path(root,'tables/all_TME_state_LR_descriptive.tsv'),sep='\t')
